export function Throttle({
  interval = {{interval}},
  scenario = "{{scenario}}",
  showBlocked = {{showBlocked}},
  accent = "{{accent}}",
}) {
  const run = { position: "absolute", top: 2, width: 16, height: 16, borderRadius: 999, background: accent };
  const blocked = { position: "absolute", top: 5, width: 10, height: 10, borderRadius: 999, background: "#24143033" };
  return (
    <div style={{ width: "100%", maxWidth: 320, padding: 16, background: "#FAF7F2", border: "1px solid #24143022", borderRadius: 12, fontFamily: "system-ui, sans-serif", fontSize: 12, color: "#241430aa" }}>
      <p style={{ margin: "0 0 8px", textTransform: "capitalize" }}>{scenario} events, one handled every {interval}ms</p>
      <div style={{ position: "relative", height: 22, background: "#24143011", borderRadius: 999 }}>
        <span style={{ ...run, left: "4%" }} />
        {showBlocked && <span style={{ ...blocked, left: "14%" }} />}
        {showBlocked && <span style={{ ...blocked, left: "20%" }} />}
        <span style={{ ...run, left: "30%" }} />
        {showBlocked && <span style={{ ...blocked, left: "40%" }} />}
        <span style={{ ...run, left: "56%" }} />
      </div>
      <p style={{ margin: "8px 0 0" }}>Solid dots run the handler &mdash; the rest are skipped until the interval passes</p>
    </div>
  );
}
